; Sets cave_number to the next cave from the cave table. After intermission 4 it sets cave A and the next level, at most 4.
next_cave
        lda cave_number
        asl
        tax
        lda cave_sequence-2,x           ; Reads cave_sequence: two bytes for each cave, cave_number 1-based.
        cmp #$15
        bne next_cave_store
; not executed $8be3-$8bec
