        cmp #$04
        beq next_cave_wrap
        inc level
next_cave_wrap
        lda #$01
next_cave_store
        sta cave_number
        rts
; Counts the remaining time down to 0. Each unit adds level plus 1 to the score with a sound. Then goes to the next cave.
count_time_bonus
