        inx
        cpx #$06
        bne time_bonus_clear
        lda level
        clc
        adc #$01
        sta $53                         ; Points for each time unit: level plus 1.
        lda #$00
        sta cave_end_state
        sta view_row_ptrs
        lda #$d0                        ; Start pitch of the bonus sound.
        sta view_row_ptrs_hi
        jsr check_time
        jsr stop_all_sound
time_bonus_loop
        lda cave_end_state
        bne time_bonus_done
        jsr decrement_time
        jsr add_points
        jsr bonus_tick_sound
        bne time_bonus_loop
time_bonus_done
        jsr play_time_tick
        jsr delay_long
        jsr stop_all_sound
        jsr next_cave
        rts
; After a lost life: updates the best score and changes turns. At game over it goes back to the title and fills the score lines.
lose_life
        jsr update_best_score
        jsr end_turn
        lda game_over
        beq lose_life_done
        lda #$00
